\begin{restatable}{prop}{propcentralized}[Centralization gain]
\label{prop:strict_improvements_from_centralization}
Assume $|\mathcal B|\geq2$.
For any $k\in \mathcal{S}, b\in \mathcal{B}$, the inspection-delay SLA under the extreme efficiency prioritizing city-budget policy is strictly better (shorter) than under the extreme efficiency prioritizing Borough-budget policy:
\begin{equation}
z^{city}_{k} < z^{\mathrm{eff}}_{k,b}.
\label{eq:pooling-sla-dominance}
\end{equation}
Furthermore, the centralization gain in efficiency can be compared to the price of equity as follows
\begin{equation}
\begin{aligned}
  &{\textnormal{centralization gain}
    \geq\textnormal{price of equity}}\\[-2pt]
  &{\qquad\Longleftrightarrow\qquad
    1-\frac{A^{\mathrm{city}}(s)^2}{A_{\mathrm{eff}}(s)^2}
    \geq\chi^2\!\left(
    q^{\mathrm{eff}}\middle\|q^{\mathrm{eq}}\right).}
\end{aligned}
\end{equation}
\end{restatable}

\begin{restatable}{prop}{propextremeefficiency}[Extreme efficiency]
\label{prop:extremeeff}
When $\gamma=1$, the optimal efficiency maximizing solution to Problem \eqref{opt-reformulated} {is given by}
\begin{equation}
    {z^{\mathrm{eff}}_{k,b}
      =\frac{{A_{\mathrm{eff}}(s)}}{E(s)}
      \sqrt{\frac{a}{s_{k,b}r_{k,b}}}.}
      \label{eq:fixed-load-efficient-endpoint}
\end{equation}
\end{restatable}

\begin{restatable}{prop}{propextremeequity}[Extreme equity]
\label{prop:extremefair}
When $\gamma=0$, {the efficiency-best equitable solution $z^{\mathrm{eq}}$ satisfies}







\begin{equation}
    {\operatorname{Cost}_{k,b}(s,z^{\mathrm{eq}})=M_k,
      \qquad k\in\mathcal S,\ b\in\mathcal B.}
\end{equation}


\end{restatable}

\begin{restatable}{prop}{reformulation}[Equivalent reciprocal-capacity representation]
\label{prop:opt-reformulation}
{Fix $s$ with $E(s)>0$ and a convex loss $L$. The fixed-load design
problem is equivalent to the tail-threshold-only problem}
\begin{equation}
  \min_{z>0}\ L(z)
  \quad\textnormal{subject to}\quad
  \sum_{k,b}\frac{a}{z_{k,b}}\leq E(s).
  \label{opt-reformulated}
\end{equation}
\end{restatable}
We use this representation in the analysis below. In \Cref{app:fixed-load-theory-proofs}, we detail the transformation, the construction of supporting Borough capacities and GPS
weights, and establish uniqueness when the reciprocal-capacity constraint is binding.

\begin{restatable}{prop}{fixedloadalignment}[Price of equity]
\label{prop:costofequity}
The price of equity is
\begin{align}
\operatorname{PoE}_C(s)
&:=\frac{G(s,z^{\mathrm{eq}})}{G(s,z^{\mathrm{eff}})}-1\notag\\[-2pt]
&=\frac{A_{\mathrm{eff}}(s)^2}{E(s)G(s,z^{\mathrm{eff}})}\notag\\[-2pt]
&\quad\times \chi^2\!\left(q^{\mathrm{eff}}\middle\|q^{\mathrm{eq}}\right)
 \label{eq:price-of-equity-chi-square}\\[-2pt]
&\leq \frac{1}{G(s,z^{\mathrm{eff}})}\sum_{k,b}\lambda_{k,b}\notag\\[-2pt]
&\quad\times\left[
 \begin{gathered}
 \max_{b'\in\mathcal B}\operatorname{Cost}_{k,b'}(s,z^{\mathrm{eff}})\\[-2pt]
 {}-\operatorname{Cost}_{k,b}(s,z^{\mathrm{eff}})
 \end{gathered}\right].\notag
\end{align}
The price is zero if and only if
$q^{\mathrm{eq}}=q^{\mathrm{eff}}$, equivalently if and only if
$\operatorname{Cost}_{k,b}(s,z^{\mathrm{eff}})$ is constant across Boroughs for each  category $k$.  Moreover, suppose the fixed noninspection burden
$r_{k,b}D_{k,b}\left(1-s_{k,b}/\lambda_{k,b}\right)$ is constant across
Boroughs within each category.
Then, writing $z^{\mathrm{eff}}(C)$ for the efficient solution at capacity $C$,
\begin{equation}
\operatorname{PoE}_{C'}(s)
=\frac{C-\sum_{k,b}s_{k,b}}
       {C'-\sum_{k,b}s_{k,b}}
 \frac{G(s,z^{\mathrm{eff}}(C))}{G(s,z^{\mathrm{eff}}(C'))}
 \operatorname{PoE}_{C}(s)
\label{eq:poe-capacity-scaling}
\end{equation}
for all $C'>C>\sum_{k,b}s_{k,b}$.
The multiplicative factor in Eq.~\eqref{eq:poe-capacity-scaling} is less than one whenever
$\sum_{k,b}(\lambda_{k,b}-s_{k,b})r_{k,b}D_{k,b}>0$; it equals one when this fixed noninspection component is zero.
\end{restatable}
